import * as React from 'react'
import gridColours from '../data/grid-colours.json'

const AccentDots: React.FC = () => {
  // Shuffle and pick 10 on each render
  const dots = React.useMemo(() => {
    const shuffled = [...gridColours]
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]]
    }
    return shuffled.slice(0, 10)
  }, [])

  return (
    <div className="accent-line">
      {dots.map((colour, index) => (
        <span
          key={index}
          className="accent-dot"
          style={{
            '--dot-colour': colour,
            '--dot-delay': `${index * 50}ms`,
            '--breath-delay': `${index * 0.4}s`,
          } as React.CSSProperties}
        />
      ))}
    </div>
  )
}

export default AccentDots
